== 2(d)
The following is a two-qubit QFT circuit. Draw the inverse QFT circuit by reversing it.

#figure(
  cetz.canvas({
    import cetz.draw: *
    import cetz.packet: *

    let label-packet(id, pos, anchor, lbl) = packet((), (id: id), (
      mark: (pos: pos, shape: "default"),
      content: (pos: pos, anchor: anchor, body: lbl),
    ))

    // --- Original QFT (top pair) ---
    group({
      content((1.5, -0.9), $QFT_4$, anchor: "south")

      // q1 wire
      line((0.3, -0.5), (2.6, -0.5))
      content((0.9, -0.5), $H$, anchor: "center")
      content((1.65, -0.5), $R_2$, anchor: "center")
      circle((0.9, -0.5), radius: 0.07, stroke: black)
      content((0.9, -0.85), $q_1$, anchor: "north")

      // q0 wire
      line((0.3, 0.5), (2.6, 0.5))
      content((0.9, 0.5), $H$, anchor: "center")
      circle((0.9, 0.5), radius: 0.07, stroke: black)
      content((0.9, 0.85), $q_0$, anchor: "south")

      // vertical wire for controlled
      line((0.9, -0.5), (0.9, 0.5), stroke: (dash: "dot", paint: black))
      circle((0.9, 0.5), radius: 0.07, fill: black)
    })

    // --- Inverse QFT (bottom pair) ---
    group({
      translate((0, 2.2))
      content((1.5, -0.9), $QFT_4^dagger$, anchor: "south")

      // q1 wire
      line((0.3, -0.5), (2.6, -0.5))
      content((0.9, -0.5), $H$, anchor: "center")
      content((1.65, -0.5), $R_2^dagger$, anchor: "center")
      circle((0.9, -0.5), radius: 0.07, stroke: black)
      content((0.9, -0.85), $q_1$, anchor: "north")

      // q0 wire
      line((0.3, 0.5), (2.6, 0.5))
      content((0.9, 0.5), $H$, anchor: "center")
      circle((0.9, 0.5), radius: 0.07, stroke: black)
      content((0.9, 0.85), $q_0$, anchor: "south")

      // vertical wire for controlled
      line((0.9, -0.5), (0.9, 0.5), stroke: (dash: "dot", paint: black))
      circle((0.9, 0.5), radius: 0.07, fill: black)
    })
  }),
  caption: [Two-qubit QFT circuit (top) and its inverse (bottom).]
)

The inverse QFT is obtained by reversing the order of gates and replacing every $R_m$ by $R_m^dagger$. Explicitly: Hadamard on $q_0$ → controlled-$R_2^dagger$ from $q_0$ (control) to $q_1$ (target) → Hadamard on $q_1$.

